#!/usr/bin/env node
/**
 * Differential harness: run the reference executable and the Node port with
 * identical argv and compare stdout, stderr and exit code byte for byte.
 *
 * The PyInstaller banner embeds the process id, so that one number is
 * normalised before comparing. Everything else must match exactly.
 */

import { spawnSync } from 'node:child_process';

const EXE = '/workspace/dataset/test17_executable';
const PORT = ['/output/test17.mjs'];

const normalise = (text) => text.replace(/\[PYI-\d+:ERROR\]/g, '[PYI-PID:ERROR]');

export function runPair(argv) {
  const a = spawnSync(EXE, argv, { encoding: 'latin1', maxBuffer: 1 << 26 });
  const b = spawnSync(process.execPath, [...PORT, ...argv], { encoding: 'latin1', maxBuffer: 1 << 26 });
  return {
    argv,
    ok: a.stdout === b.stdout
      && normalise(a.stderr) === normalise(b.stderr)
      && a.status === b.status,
    ref: { stdout: a.stdout, stderr: normalise(a.stderr), status: a.status },
    port: { stdout: b.stdout, stderr: normalise(b.stderr), status: b.status },
  };
}

function show(result) {
  const { ref, port } = result;
  console.log(`\nMISMATCH argv=${JSON.stringify(result.argv)}`);
  if (ref.stdout !== port.stdout) {
    console.log(`  stdout ref : ${JSON.stringify(ref.stdout)}`);
    console.log(`  stdout port: ${JSON.stringify(port.stdout)}`);
  }
  if (ref.stderr !== port.stderr) {
    console.log(`  stderr ref : ${JSON.stringify(ref.stderr)}`);
    console.log(`  stderr port: ${JSON.stringify(port.stderr)}`);
  }
  if (ref.status !== port.status) {
    console.log(`  exit ref=${ref.status} port=${port.status}`);
  }
}

/** @param {string[][]} cases */
export function compareAll(cases, label = 'cases') {
  let pass = 0;
  const failures = [];
  for (const argv of cases) {
    const result = runPair(argv);
    if (result.ok) pass += 1;
    else failures.push(result);
  }
  for (const failure of failures) show(failure);
  console.log(`\n${label}: ${pass}/${cases.length} match, ${failures.length} mismatch`);
  return failures.length;
}

#!/usr/bin/env node
/**
 * Node.js port of /workspace/dataset/construct/test17.py.
 *
 * The Python original builds seven little-endian fields with `construct` and
 * prints each resulting bytes object. This file keeps the same statement order
 * so that a failure part-way through produces the same traceback - the
 * `atSourceLine` numbers are the line numbers of the corresponding statements
 * in the Python source, which the frozen build reports on error.
 *
 * Usage:
 *   node test17.mjs --a INT --b INT --c STR --d INT --e STR --f INT --g INT
 */

import { ArgumentParser, HelpRequested, ParserError, int, str } from './lib/argparse/index.mjs';
import { Bytes, Int8ul, Int16ul } from './lib/construct/index.mjs';
import { PyException } from './lib/python/exceptions.mjs';
import { encodeUtf8 } from './lib/python/codec.mjs';
import { pyMod } from './lib/python/int.mjs';
import { pyBytesRepr } from './lib/python/repr.mjs';
import { getPythonArgv } from './lib/runtime/argv.mjs';
import { PROG_NAME } from './lib/runtime/config.mjs';
import { flush, printLine, writeStderr, writeStdout } from './lib/runtime/stdio.mjs';
import { atSourceLine, renderTraceback } from './lib/runtime/traceback.mjs';

const BYTE_MODULUS = 256n;

function buildParser() {
  const parser = new ArgumentParser(PROG_NAME);
  parser.addArgument(['--a'], { type: int, required: true });
  parser.addArgument(['--b'], { type: int, required: true });
  parser.addArgument(['--c'], { type: str, required: true });
  parser.addArgument(['--d'], { type: int, required: true });
  parser.addArgument(['--e'], { type: str, required: true });
  parser.addArgument(['--f'], { type: int, required: true });
  parser.addArgument(['--g'], { type: int, required: true });
  return parser;
}

function main() {
  const args = buildParser().parseArgs(getPythonArgv());

  const format1 = atSourceLine(16, () => Int8ul.build(args.a)); // 构建头字节
  const format2 = atSourceLine(17, () => Int16ul.build(args.b)); // 构建长度字段
  const format3 = atSourceLine(18, () => Bytes(args.d).build(encodeUtf8(args.c))); // 构建第一个数据块
  const format4 = atSourceLine(19, () => Int8ul.build(args.f)); // 构建分隔符
  const format5 = atSourceLine(20, () => Bytes(args.g).build(encodeUtf8(args.e))); // 构建第二个数据块
  // 构建校验和，确保在字节范围内
  const format6 = atSourceLine(21, () => Int8ul.build(pyMod(args.f + args.g, BYTE_MODULUS)));
  // 构建最终校验，确保在字节范围内
  const format7 = atSourceLine(22, () => Int8ul.build(pyMod(args.a + args.b, BYTE_MODULUS)));

  printLine(pyBytesRepr(format1));
  printLine(pyBytesRepr(format2));
  printLine(pyBytesRepr(format3));
  printLine(pyBytesRepr(format4));
  printLine(pyBytesRepr(format5));
  printLine(pyBytesRepr(format6));
  printLine(pyBytesRepr(format7));
}

try {
  main();
  flush(0);
} catch (err) {
  if (err instanceof HelpRequested) {
    writeStdout(err.text);
    flush(0);
  } else if (err instanceof ParserError) {
    writeStderr(err.render());
    flush(2);
  } else if (err instanceof PyException) {
    writeStderr(renderTraceback(err));
    flush(1);
  } else {
    throw err;
  }
}

/**
 * CPython's int(str) conversion.
 *
 * argparse's `type=int` calls this, so the accepted grammar has to match
 * exactly - including Unicode whitespace padding, underscore digit grouping,
 * and non-ASCII decimal digits such as U+0665 ARABIC-INDIC DIGIT FIVE.
 */

import { PyValueError } from './exceptions.mjs';
import { codePoints, decimalDigitValue, isIntLiteralWhitespace } from './unicode.mjs';
import { pyStrRepr } from './repr.mjs';

const UNDERSCORE = 0x5f;
const PLUS = 0x2b;
const MINUS = 0x2d;

/**
 * Parse a Python base-10 integer literal.
 *
 * Grammar, after stripping leading and trailing whitespace:
 *   ['+' | '-'] digit (['_'] digit)*
 * Note there is no whitespace allowed after the sign, and an underscore is
 * only legal between two digits.
 *
 * @returns {bigint} the value, with arbitrary precision like Python's int
 * @throws {PyValueError} if the text is not a valid literal
 */
export function pyInt(text) {
  const invalid = () => new PyValueError(
    `invalid literal for int() with base 10: ${pyStrRepr(text)}`,
  );

  const points = [...codePoints(text)];
  let start = 0;
  let end = points.length;
  while (start < end && isIntLiteralWhitespace(points[start])) start += 1;
  while (end > start && isIntLiteralWhitespace(points[end - 1])) end -= 1;

  let negative = false;
  if (start < end && (points[start] === PLUS || points[start] === MINUS)) {
    negative = points[start] === MINUS;
    start += 1;
  }
  if (start >= end) throw invalid();

  let value = 0n;
  let digitCount = 0;
  let previousWasUnderscore = false;

  for (let i = start; i < end; i += 1) {
    const cp = points[i];

    if (cp === UNDERSCORE) {
      // Legal only between digits: never leading, doubled, or trailing.
      if (digitCount === 0 || previousWasUnderscore) throw invalid();
      previousWasUnderscore = true;
      continue;
    }

    const digit = decimalDigitValue(cp);
    if (digit < 0) throw invalid();
    value = value * 10n + BigInt(digit);
    digitCount += 1;
    previousWasUnderscore = false;
  }

  if (digitCount === 0 || previousWasUnderscore) throw invalid();
  return negative ? -value : value;
}

/** Python's `%` on integers: the result carries the sign of the divisor. */
export function pyMod(value, modulus) {
  const remainder = value % modulus;
  if (remainder !== 0n && (remainder < 0n) !== (modulus < 0n)) {
    return remainder + modulus;
  }
  return remainder;
}

/**
 * Python-compatible Unicode character predicates.
 *
 * CPython's `int(str)` and `str.__repr__` consult the Unicode database directly,
 * so a faithful port needs the same classifications rather than JavaScript's
 * (subtly different) built-in equivalents.
 */

// Codepoints for which CPython's Py_UNICODE_ISSPACE() is true. This is *not*
// the same set as JavaScript's /\s/u: Python includes the C0 separators
// U+001C..U+001F and U+0085 (NEL) but excludes U+FEFF (ZWNBSP).
const PY_UNICODE_WHITESPACE = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, // \t \n \v \f \r
  0x1c, 0x1d, 0x1e, 0x1f, // FS GS RS US
  0x20, // SPACE
  0x85, // NEL
  0xa0, // NBSP
  0x1680, // OGHAM SPACE MARK
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a,
  0x2028, // LINE SEPARATOR
  0x2029, // PARAGRAPH SEPARATOR
  0x202f, // NARROW NO-BREAK SPACE
  0x205f, // MEDIUM MATHEMATICAL SPACE
  0x3000, // IDEOGRAPHIC SPACE
]);

// The narrower ASCII-only set recognised by the C macro Py_ISSPACE().
const ASCII_WHITESPACE = new Set([0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x20]);

const DECIMAL_DIGIT = /\p{Nd}/u;

// str.isprintable() is false for these categories; U+0020 is the one exception.
const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

/** Equivalent of CPython's Py_UNICODE_ISSPACE(). */
export function isPyWhitespace(codePoint) {
  return PY_UNICODE_WHITESPACE.has(codePoint);
}

/**
 * Whitespace as int(str) sees it - a hybrid of the two sets above, and a
 * genuine CPython quirk rather than an approximation.
 *
 * int() first runs the text through _PyUnicode_TransformDecimalAndSpaceToASCII,
 * which rewrites every *non-ASCII* Py_UNICODE_ISSPACE character to a plain
 * space, and then parses the result with PyLong_FromString, which strips using
 * the ASCII-only Py_ISSPACE. So U+0085 and U+00A0 pad an integer literal fine,
 * while the ASCII separators U+001C..U+001F do not - int('\x1c12') raises even
 * though '\x1c'.isspace() is True.
 */
export function isIntLiteralWhitespace(codePoint) {
  return codePoint < 0x80
    ? ASCII_WHITESPACE.has(codePoint)
    : PY_UNICODE_WHITESPACE.has(codePoint);
}

function isDecimalDigit(codePoint) {
  // Lone surrogates can never be Nd and String.fromCodePoint would produce an
  // unpaired unit, so short-circuit them.
  if (codePoint >= 0xd800 && codePoint <= 0xdfff) return false;
  return DECIMAL_DIGIT.test(String.fromCodePoint(codePoint));
}

// Walking back more than this from a digit means the Unicode database grew a
// run far larger than anything that has ever existed; bail out rather than spin.
const MAX_RUN_SCAN = 4096;

/**
 * Value 0-9 of a Unicode decimal digit, or -1 if the codepoint is not one.
 * Mirrors CPython's Py_UNICODE_TODECIMAL(), which is what int(str) uses.
 *
 * Unicode guarantees that decimal digits appear as blocks of exactly ten
 * consecutive codepoints ordered 0..9. Several blocks can sit back-to-back
 * (U+1D7CE..U+1D7FF is one unbroken run of fifty mathematical digits), so the
 * digit's value is its offset from the start of the maximal run, modulo ten.
 */
export function decimalDigitValue(codePoint) {
  if (codePoint >= 0x30 && codePoint <= 0x39) return codePoint - 0x30; // ASCII fast path
  if (!isDecimalDigit(codePoint)) return -1;

  let runStart = codePoint;
  for (let steps = 0; steps < MAX_RUN_SCAN; steps += 1) {
    if (runStart === 0 || !isDecimalDigit(runStart - 1)) break;
    runStart -= 1;
  }
  return (codePoint - runStart) % 10;
}

/** Equivalent of Python's str.isprintable() for a single codepoint. */
export function isPyPrintable(codePoint) {
  if (codePoint === 0x20) return true;
  if (codePoint >= 0xd800 && codePoint <= 0xdfff) return false; // Cs
  return !NON_PRINTABLE.test(String.fromCodePoint(codePoint));
}

/** Iterate a JS string as codepoints, yielding lone surrogates as-is. */
export function* codePoints(text) {
  for (let i = 0; i < text.length; i += 1) {
    const unit = text.charCodeAt(i);
    if (unit >= 0xd800 && unit <= 0xdbff && i + 1 < text.length) {
      const low = text.charCodeAt(i + 1);
      if (low >= 0xdc00 && low <= 0xdfff) {
        yield (unit - 0xd800) * 0x400 + (low - 0xdc00) + 0x10000;
        i += 1;
        continue;
      }
    }
    yield unit;
  }
}

/**
 * The callables Python passes as argparse's `type=`. The `name` field is what
 * argparse interpolates into "invalid <name> value: ...".
 */

import { pyInt } from '../python/int.mjs';

export const int = { name: 'int', convert: pyInt };

export const str = { name: 'str', convert: (text) => text };
/**
 * Recovering argv exactly as CPython sees it.
 *
 * Node decodes process.argv as UTF-8 with lossy replacement, so a byte
 * sequence like 0xFF arrives as U+FFFD and becomes indistinguishable from a
 * genuine replacement character. CPython instead applies the `surrogateescape`
 * handler, preserving the original bytes as lone surrogates - which is exactly
 * why the reference build can go on to raise UnicodeEncodeError.
 *
 * On Linux the untouched bytes are still available from /proc/self/cmdline, so
 * read them there and decode them ourselves.
 */

import { readFileSync } from 'node:fs';

import { fsDecode } from '../python/codec.mjs';

const CMDLINE = '/proc/self/cmdline';

/** Split the NUL-delimited cmdline into per-argument byte arrays. */
function readRawArguments() {
  // 'latin1' maps each byte to the codepoint of the same value, giving us the
  // raw bytes without going near typed arrays.
  const raw = readFileSync(CMDLINE, 'latin1');
  const text = raw.endsWith('\0') ? raw.slice(0, -1) : raw;
  if (text === '') return [];
  return text.split('\0').map((entry) => {
    const bytes = [];
    for (let i = 0; i < entry.length; i += 1) bytes.push(entry.charCodeAt(i));
    return bytes;
  });
}

/**
 * The user-supplied arguments, decoded the way Python decodes them.
 * Falls back to Node's own view if /proc is unavailable.
 */
export function getPythonArgv() {
  const userCount = process.argv.length - 2;
  if (userCount <= 0) return [];

  try {
    const entries = readRawArguments();
    // The user's arguments are always the trailing entries: anything Node adds
    // (the interpreter path, exec flags, the script path) comes first.
    if (entries.length >= userCount) {
      return entries.slice(entries.length - userCount).map(fsDecode);
    }
  } catch {
    // Not Linux, or /proc not mounted - fall through.
  }
  return process.argv.slice(2);
}
/**
 * Python 3 repr() for str and bytes.
 *
 * These drive both the program's stdout (print of a bytes object) and
 * argparse's "invalid int value: %r" diagnostics, so they must be exact.
 */

import { codePoints, isPyPrintable } from './unicode.mjs';

const BACKSLASH = 0x5c;
const SINGLE_QUOTE = 0x27;
const DOUBLE_QUOTE = 0x22;

function hex(value, width) {
  return value.toString(16).padStart(width, '0');
}

/**
 * Python picks the quote character that needs the least escaping: a single
 * quote normally, switching to a double quote only when the value contains a
 * single quote but no double quote.
 */
function chooseQuote(hasSingle, hasDouble) {
  return hasSingle && !hasDouble ? DOUBLE_QUOTE : SINGLE_QUOTE;
}

/** Python 3 `repr(some_str)`. */
export function pyStrRepr(text) {
  const points = [...codePoints(text)];
  const quote = chooseQuote(
    points.includes(SINGLE_QUOTE),
    points.includes(DOUBLE_QUOTE),
  );

  let out = String.fromCharCode(quote);
  for (const cp of points) {
    if (cp === quote || cp === BACKSLASH) out += `\\${String.fromCharCode(cp)}`;
    else if (cp === 0x09) out += '\\t';
    else if (cp === 0x0a) out += '\\n';
    else if (cp === 0x0d) out += '\\r';
    else if (cp < 0x20 || cp === 0x7f) out += `\\x${hex(cp, 2)}`;
    else if (cp < 0x7f) out += String.fromCharCode(cp);
    else if (isPyPrintable(cp)) out += String.fromCodePoint(cp);
    else if (cp < 0x100) out += `\\x${hex(cp, 2)}`;
    else if (cp < 0x10000) out += `\\u${hex(cp, 4)}`;
    else out += `\\U${hex(cp, 8)}`;
  }
  return out + String.fromCharCode(quote);
}

/**
 * Python 3 `repr(some_bytes)`, given the bytes as an array of 0-255 integers.
 * Only \t, \n, \r and \\ get short escapes; every other non-ASCII-printable
 * byte becomes a two-digit lowercase \xHH.
 */
export function pyBytesRepr(bytes) {
  const quote = chooseQuote(
    bytes.includes(SINGLE_QUOTE),
    bytes.includes(DOUBLE_QUOTE),
  );

  let out = `b${String.fromCharCode(quote)}`;
  for (const byte of bytes) {
    if (byte === quote || byte === BACKSLASH) out += `\\${String.fromCharCode(byte)}`;
    else if (byte === 0x09) out += '\\t';
    else if (byte === 0x0a) out += '\\n';
    else if (byte === 0x0d) out += '\\r';
    else if (byte < 0x20 || byte >= 0x7f) out += `\\x${hex(byte, 2)}`;
    else out += String.fromCharCode(byte);
  }
  return out + String.fromCharCode(quote);
}

/**
 * A faithful subset of Python's argparse.ArgumentParser.
 *
 * Only what test17.py exercises is modelled: long options that each take one
 * value, the implicit -h/--help, and required-argument checking. The parsing
 * order and error precedence follow CPython's _parse_known_args so that
 * diagnostics come out in the same order for the same input.
 */

import { pyStrRepr } from '../python/repr.mjs';
import { PyException } from '../python/exceptions.mjs';
import { HelpRequested, ParserError } from './exceptions.mjs';
import { formatHelp, formatUsage } from './formatter.mjs';

// argparse's _negative_number_matcher. Python's \d is Unicode-aware, so
// non-ASCII decimal digits count here too.
const NEGATIVE_NUMBER = /^-[\p{Nd}]+$|^-[\p{Nd}]*\.[\p{Nd}]+$/u;

const PREFIX_CHARS = '-';

/** How argparse names an action in an error message. */
function actionName(action) {
  return action.optionStrings.join('/');
}

export class ArgumentParser {
  constructor(prog) {
    this.prog = prog;
    this.actions = [];
    this.optionStringActions = new Map();

    this.addArgument(['-h', '--help'], {
      nargs: 0,
      dest: 'help',
      help: 'show this help message and exit',
    });
  }

  addArgument(optionStrings, options = {}) {
    const dest = options.dest ?? optionStrings[optionStrings.length - 1].replace(/^-+/, '');
    const action = {
      optionStrings,
      dest,
      nargs: options.nargs ?? 1,
      type: options.type ?? null,
      required: options.required ?? false,
      metavar: options.metavar ?? dest.toUpperCase(),
      help: options.help ?? null,
    };
    this.actions.push(action);
    for (const flag of optionStrings) this.optionStringActions.set(flag, action);
    return action;
  }

  formatUsage() {
    return formatUsage(this.prog, this.actions);
  }

  formatHelp() {
    return formatHelp(this.prog, this.actions);
  }

  error(message) {
    throw new ParserError(this.formatUsage(), this.prog, message);
  }

  /**
   * Classify one argv token. Returns null when it is a plain value, otherwise
   * a tuple describing which option it names (action === null for an option
   * the parser does not know).
   *
   * `sep` records how an inline value was attached: '=' for --opt=value, ''
   * for a value glued onto a short flag, null when there is no inline value.
   * argparse consults it to decide whether a glued value on a zero-argument
   * flag is an error or a run of further short flags.
   */
  parseOptional(argString) {
    if (argString === '') return null;
    if (!PREFIX_CHARS.includes(argString[0])) return null;

    const exact = this.optionStringActions.get(argString);
    if (exact) {
      return { action: exact, optionString: argString, explicitArg: null, sep: null };
    }

    if (argString.length === 1) return null; // a bare "-" is a value

    if (argString.includes('=')) {
      const splitAt = argString.indexOf('=');
      const optionString = argString.slice(0, splitAt);
      const known = this.optionStringActions.get(optionString);
      if (known) {
        return {
          action: known,
          optionString,
          explicitArg: argString.slice(splitAt + 1),
          sep: '=',
        };
      }
    }

    const matches = this.getOptionTuples(argString);
    if (matches.length > 1) {
      const names = matches.map((match) => match.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${names}`);
    }
    if (matches.length === 1) return matches[0];

    // Nothing matched. A token that merely looks like a negative number is a
    // value, because no option string here looks like one.
    if (NEGATIVE_NUMBER.test(argString)) return null;
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, explicitArg: null, sep: null };
  }

  /** Unambiguous-prefix matching, e.g. "--he" -> "--help". */
  getOptionTuples(argString) {
    const matches = [];

    if (PREFIX_CHARS.includes(argString[1])) {
      const splitAt = argString.indexOf('=');
      const prefix = splitAt >= 0 ? argString.slice(0, splitAt) : argString;
      const explicitArg = splitAt >= 0 ? argString.slice(splitAt + 1) : null;
      const sep = splitAt >= 0 ? '=' : null;
      for (const [flag, action] of this.optionStringActions) {
        if (flag.startsWith(prefix)) {
          matches.push({ action, optionString: flag, explicitArg, sep });
        }
      }
      return matches;
    }

    // Single-dash: either an exact short option with the rest glued on as its
    // value, or a prefix of a longer option string.
    const shortPrefix = argString.slice(0, 2);
    const shortExplicitArg = argString.slice(2);
    for (const [flag, action] of this.optionStringActions) {
      if (flag === shortPrefix) {
        matches.push({ action, optionString: flag, explicitArg: shortExplicitArg, sep: '' });
      } else if (flag.startsWith(argString)) {
        matches.push({ action, optionString: flag, explicitArg: null, sep: null });
      }
    }
    return matches;
  }

  /** Apply an action's `type` callable, mapping ValueError to a usage error. */
  getValue(action, optionString, text) {
    if (!action.type) return text;
    try {
      return action.type.convert(text);
    } catch (err) {
      if (err instanceof PyException) {
        this.error(
          `argument ${optionString}: invalid ${action.type.name} value: ${pyStrRepr(text)}`,
        );
      }
      throw err;
    }
  }

  /**
   * Consume the option at `start` and return the next index to look at.
   *
   * The loop exists for glued short flags: "-h5" names the zero-argument -h
   * and leaves "5" over, which argparse re-reads as "-5". If that names
   * another flag the loop continues; if not, the leftover is set aside as an
   * unrecognised argument rather than being an error outright.
   */
  consumeOptional(start, argStrings, isOption, tuples, namespace, extras) {
    let { action, optionString, explicitArg, sep } = tuples[start];
    const pending = [];
    let stop = start + 1;

    for (;;) {
      if (action === null) {
        extras.push(argStrings[start]);
        return start + 1;
      }

      if (explicitArg !== null) {
        const takesNoValue = action.nargs === 0;

        if (takesNoValue && !PREFIX_CHARS.includes(optionString[1]) && explicitArg !== '') {
          if (sep || PREFIX_CHARS.includes(explicitArg[0])) {
            this.error(
              `argument ${actionName(action)}: ignored explicit argument ${pyStrRepr(explicitArg)}`,
