          pending.push({ action, optionString });

          const next = optionString[0] + explicitArg[0];
          const nextAction = this.optionStringActions.get(next);
          if (!nextAction) {
            extras.push(optionString[0] + explicitArg);
            break;
          }
          action = nextAction;
          optionString = next;
          explicitArg = explicitArg.slice(1);
          if (explicitArg === '') {
            sep = null;
            explicitArg = null;
          } else if (explicitArg[0] === '=') {
            sep = '=';
            explicitArg = explicitArg.slice(1);
          } else {
            sep = '';
          }
          continue;
        }

        if (takesNoValue) {
          this.error(
            `argument ${actionName(action)}: ignored explicit argument ${pyStrRepr(explicitArg)}`,
          );
        }
        pending.push({ action, optionString, raw: explicitArg });
        break;
      }

      if (action.nargs === 0) {
        pending.push({ action, optionString });
        break;
      }

      if (start + 1 < argStrings.length && !isOption[start + 1]) {
        pending.push({ action, optionString, raw: argStrings[start + 1] });
        stop = start + 2;
        break;
      }
      this.error(`argument ${optionString}: expected one argument`);
    }

    // Actions run only after the whole token has been decomposed, which is why
    // "-h5" still prints help despite leaving an unrecognised "-5" behind.
    for (const item of pending) this.takeAction(item, namespace);
    return stop;
  }

  takeAction({ action, optionString, raw }, namespace) {
    if (action.nargs === 0) {
      if (action.dest === 'help') throw new HelpRequested(this.formatHelp());
      namespace[action.dest] = true;
      return;
    }
    namespace[action.dest] = this.getValue(action, optionString, raw);
  }

  /** @returns {[Record<string, unknown>, string[]]} namespace and leftovers */
  parseKnownArgs(argStrings) {
    // Pass one: decide for every token whether it is an option or a value.
    // Everything after the first "--" is forced to be a value.
    const tuples = [];
    const isOption = [];
    let afterDoubleDash = false;
    for (const argString of argStrings) {
      if (afterDoubleDash) {
        tuples.push(null);
        isOption.push(false);
      } else if (argString === '--') {
        afterDoubleDash = true;
        tuples.push(null);
        isOption.push(false);
      } else {
        const tuple = this.parseOptional(argString);
        tuples.push(tuple);
        isOption.push(tuple !== null);
      }
    }

    // Pass two: consume options left to right. With no positionals declared,
    // every value token that no option claims falls through to `extras`.
    const namespace = Object.create(null);
    const extras = [];
    let i = 0;
    while (i < argStrings.length) {
      if (!isOption[i]) {
        extras.push(argStrings[i]);
        i += 1;
        continue;
      }
      i = this.consumeOptional(i, argStrings, isOption, tuples, namespace, extras);
    }

    // Required options are reported together, in declaration order.
    const missing = this.actions
      .filter((action) => action.required && !(action.dest in namespace))
      .map(actionName);
    if (missing.length) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  parseArgs(argStrings) {
    const [namespace, extras] = this.parseKnownArgs(argStrings);
    if (extras.length) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return namespace;
  }
}

